corrected_code:
export const paymentRouter = router({
  deletePaymentMethod: protectedProcedure
    .input(z.object({ paymentMethodId: z.string() }))
    .mutation(async ({ input, ctx }) => {
      const pm = await ctx.prisma.paymentMethod.findFirst({
        where: { id: input.paymentMethodId, customerId: ctx.user.customerId },
      });
      if (!pm) throw new TRPCError({ code: 'FORBIDDEN', message: 'Payment method not owned by customer' });
      await stripe.paymentMethods.detach(pm.stripePaymentMethodId);
      await ctx.prisma.paymentMethod.delete({ where: { id: pm.id } });
      return { deleted: true };
    }),
});
